<?php if ($show && $c['status'] !== 'open'): ?><td class="num"><?= $l['status'] === 'posted' || $c['status'] === 'posted' ? qty($l['posted_qty'], $d) : ($l['variance'] !== null ? ($l['variance'] > 0 ? '+' : '') . qty($l['variance'], $d) : '') ?></td><?php endif ?></tr><?php endforeach ?>
